import React, { useEffect, useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Map, { Marker, Source, Layer, NavigationControl } from 'react-map-gl/maplibre';
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import { ArrowLeft, Clock, Activity, Play, Pause, Plane, Truck, Compass, Layers, X, Camera, Crosshair } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';
import { getVehicleColor } from './ManageFleetPage';

export default function VehicleHistoryPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { theme } = useTheme();

  const [history, setHistory] = useState([]);
  const [vehicle, setVehicle] = useState(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLive, setIsLive] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isHudExpanded, setIsHudExpanded] = useState(true);

  // NEW: Toggle to lock/unlock the camera tracking
  const [autoFollow, setAutoFollow] = useState(true);

  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 16,
    pitch: 65,
    bearing: -20
  });

  useEffect(() => {
    fetch('http://localhost:8080/api/fleet/vehicles')
      .then(res => res.json())
      .then(data => {
        const found = data.find(v => v.id === id);
        if (found) setVehicle(found);
      });

    fetch(`http://localhost:8080/api/fleet/vehicles/${id}/history`)
      .then(res => (res.ok ? res.json() : []))
      .then(data => {
        if (data && data.length > 0) {
          setHistory(data);
          setCurrentIndex(data.length - 1);
        }
      })
      .catch(err => console.error("History fetch failed:", err));
  }, [id]);

  useEffect(() => {
    if (!isLive) return;
    const socket = new SockJS('http://localhost:8080/ws-telemetry');
    const stompClient = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        stompClient.subscribe(`/topic/telemetry.${id}.position`, message => {
          const payload = JSON.parse(message.body);
          if (!payload.timestamp) payload.timestamp = new Date().toISOString();

          setHistory(prev => {
            const next = [...prev, payload];
            setCurrentIndex(next.length - 1);
            return next;
          });
        });
      },
    });

    stompClient.activate();
    return () => stompClient.deactivate();
  }, [id, isLive]);

  useEffect(() => {
    if (!isPlaying || isLive || history.length === 0) return;
    const interval = setInterval(() => {
      setCurrentIndex(prev => {
        if (prev >= history.length - 1) {
          setIsPlaying(false);
          return prev;
        }
        return prev + 1;
      });
    }, 100);
    return () => clearInterval(interval);
  }, [isPlaying, isLive, history.length]);

  const activePoint = history[currentIndex];

  // Camera tracking only fires if 'autoFollow' is true
  useEffect(() => {
    if (activePoint && autoFollow) {
      setViewState(prev => ({
        ...prev,
        longitude: activePoint.longitude,
        latitude: activePoint.latitude,
        transitionDuration: isPlaying ? 100 : 400
      }));
    }
  }, [activePoint, isPlaying, autoFollow]);

  const isDark = theme === 'dark';
  const vColor = getVehicleColor(id);
  const mapStyle = {
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: ['https://a.tile.openstreetmap.org/{z}/{x}/{y}.png'],
        tileSize: 256
      }
    },
    layers: [{ id: 'osm', type: 'raster', source: 'osm', minzoom: 0, maxzoom: 19 }]
  };

  const hudBg = isDark ? 'var(--bg-glass, rgba(18, 18, 22, 0.95))' : 'rgba(255, 255, 255, 0.95)';
  const textColor = isDark ? '#fff' : '#111';
  const subtextColor = isDark ? '#888' : '#555';
  const borderColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.1)';
  const btnBg = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';
  const btnHoverBg = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)';

  const presetButtonStyle = {
    flex: 1, background: btnBg, border: `1px solid ${borderColor}`,
    borderRadius: '6px', color: subtextColor, fontSize: '11px', padding: '6px 0',
    cursor: 'pointer', textTransform: 'uppercase', fontWeight: '600', transition: 'all 0.2s'
  };

  // FIXED: Robust FeatureCollection parsing
  const pathGeoJSON = useMemo(() => {
    if (history.length < 2 || currentIndex < 1) return null;

    // Safely filter out bad coordinates
    const validCoords = history
      .slice(0, currentIndex + 1)
      .filter(p => p && p.longitude != null && p.latitude != null)
      .map(p => [p.longitude, p.latitude]);

    if (validCoords.length < 2) return null;

    // Use a strict Mapbox-compliant FeatureCollection
    return {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature',
          geometry: {
            type: 'LineString',
            coordinates: validCoords
          }
        }
      ]
    };
  }, [history, currentIndex]);

  const isGround = vehicle?.category === 'GROUND';
  const displayAlt = isGround ? 0 : (activePoint?.altitude || 50);

  return (
    <div style={{ width: '100vw', height: '100vh', display: 'flex', flexDirection: 'column', background: isDark ? '#111' : '#eee' }}>

      {/* HEADER */}
      <div style={{
        padding: '16px 24px', background: isDark ? '#1a1a20' : '#fff', borderBottom: `1px solid ${isDark ? '#333' : '#ddd'}`,
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', zIndex: 10
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <button onClick={() => navigate(-1)} style={{ background: 'none', border: 'none', color: isDark ? '#fff' : '#000', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', fontWeight: '500' }}>
            <ArrowLeft size={16} /> Back to Fleet
          </button>
          <div style={{ width: '1px', height: '24px', background: isDark ? '#333' : '#ddd' }} />
          <h2 style={{ margin: 0, fontSize: '18px', color: isDark ? '#fff' : '#000' }}>{vehicle?.name || id}</h2>
          <span style={{ fontSize: '12px', padding: '4px 8px', borderRadius: '12px', background: `${vColor}20`, color: vColor, fontWeight: '600' }}>
            Historical DVR
          </span>
        </div>
      </div>

      {/* MAP AREA */}
      <div style={{ flex: 1, position: 'relative' }}>
        <Map
          {...viewState}
          onMove={evt => setViewState(evt.viewState)}
          mapStyle={mapStyle}
          style={{ width: '100%', height: '100%' }}
        >
          <NavigationControl position="top-left" visualizePitch={true} />

          {/* FIXED: LINE TRACE RENDERER */}
          {pathGeoJSON && (
            <Source id="vehicle-path-source" type="geojson" data={pathGeoJSON}>
              <Layer
                id="vehicle-path-layer"
                type="line"
                layout={{ 'line-join': 'round', 'line-cap': 'round' }}
                paint={{
                  'line-color': vColor,
                  'line-width': 6,
                  'line-opacity': 0.9
                }}
              />
            </Source>
          )}

          {activePoint && (
            <Marker longitude={activePoint.longitude} latitude={activePoint.latitude} anchor="bottom">
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{
                  background: vColor, color: '#000', borderRadius: '8px', padding: '6px',
                  boxShadow: `0 0 15px ${vColor}`, transform: `translateY(-${displayAlt}px)`
                }}>
                  {isGround ? <Truck size={16} /> : <Plane size={16} />}
                </div>
                <div style={{
                  width: '2px', height: `${displayAlt}px`,
                  background: `linear-gradient(to bottom, ${vColor}, transparent)`
                }} />
                <div style={{
                  width: '12px', height: '4px', background: 'rgba(0,0,0,0.6)', borderRadius: '50%', boxShadow: '0 0 4px rgba(0,0,0,0.8)'
                }} />
              </div>
            </Marker>
          )}
        </Map>

        {/* HUD OVERLAY */}
        {isHudExpanded ? (
          <div style={{
            position: 'absolute', top: '20px', right: '20px',
            background: hudBg, backdropFilter: 'blur(15px)',
            border: `1px solid ${borderColor}`, borderRadius: '16px',
            padding: '20px', color: textColor,
            boxShadow: '0 20px 40px rgba(0,0,0,0.15)', zIndex: 10,
            display: 'flex', flexDirection: 'column', gap: '22px', width: '270px'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontSize: '13px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Camera Settings</span>
              <X size={18} color={subtextColor} style={{ cursor: 'pointer' }} onClick={() => setIsHudExpanded(false)} />
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
                <div style={{ width: '42px', height: '42px', borderRadius: '12px', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center', perspective: '100px' }}>
                  <Layers size={22} color="var(--accent, #4f9dff)" style={{ transform: `rotateX(${viewState.pitch}deg)` }}/>
                </div>
                <div>
                  <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Pitch Angle</div>
                  <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.pitch)}°</div>
                </div>
              </div>
              <input type="range" min="0" max="85" value={viewState.pitch} onChange={e => setViewState(prev => ({ ...prev, pitch: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }} />
              <div style={{ display: 'flex', gap: '8px' }}>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, pitch: 0 }))}>2D Flat</button>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, pitch: 65 }))}>3D View</button>
              </div>
            </div>
            <div style={{ height: '1px', background: borderColor }} />
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
                <div style={{ width: '42px', height: '42px', borderRadius: '50%', background: btnBg, border: `1px solid ${borderColor}`, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                  <Compass size={22} color="var(--accent, #4f9dff)" style={{ transform: `rotate(${viewState.bearing}deg)` }}/>
                </div>
                <div>
                  <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Bearing</div>
                  <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.bearing)}°</div>
                </div>
              </div>
              <input type="range" min="-180" max="180" value={viewState.bearing} onChange={e => setViewState(prev => ({ ...prev, bearing: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }} />
              <div style={{ display: 'flex', gap: '8px' }}>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 0 }))}>N</button>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 90 }))}>E</button>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 180 }))}>S</button>
                <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: -90 }))}>W</button>
              </div>
            </div>
          </div>
        ) : (
          <div
            onClick={() => setIsHudExpanded(true)}
            style={{
              position: 'absolute', top: '20px', right: '20px', background: hudBg, border: `1px solid ${borderColor}`,
              borderRadius: '50%', width: '44px', height: '44px', display: 'flex', justifyContent: 'center', alignItems: 'center',
              cursor: 'pointer', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 10, color: textColor, transition: 'all 0.2s ease'
            }}
            onMouseOver={e => e.currentTarget.style.transform = 'scale(1.05)'} onMouseOut={e => e.currentTarget.style.transform = 'scale(1)'}
          >
            <Camera size={20} />
          </div>
        )}
      </div>

      {/* BOTTOM TIMELINE CONTROLS */}
      <div style={{
        padding: '24px', background: isDark ? '#1a1a20' : '#fff', borderTop: `1px solid ${isDark ? '#333' : '#ddd'}`, zIndex: 10
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '24px', maxWidth: '1200px', margin: '0 auto' }}>

          <button
            onClick={() => { setIsPlaying(!isPlaying); setIsLive(false); }}
            style={{
              width: '48px', height: '48px', borderRadius: '50%', border: 'none',
              background: isLive ? '#333' : 'var(--accent)', color: '#fff',
              display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer'
            }}
          >
            {isPlaying ? <Pause size={20} fill="currentColor"/> : <Play size={20} fill="currentColor" style={{ marginLeft: '4px' }}/>}
          </button>

          {/* NEW: Auto-Follow Camera Toggle */}
          <button
            onClick={() => setAutoFollow(!autoFollow)}
            title="Toggle Camera Auto-Follow"
            style={{
              width: '42px', height: '42px', borderRadius: '10px', border: `1px solid ${borderColor}`,
              background: autoFollow ? `${vColor}20` : btnBg,
              color: autoFollow ? vColor : subtextColor,
              display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer',
              transition: 'all 0.2s'
            }}
          >
            <Crosshair size={20} />
          </button>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', color: isDark ? '#aaa' : '#555', fontSize: '13px' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                <Clock size={14} />
                {activePoint?.timestamp ? new Date(activePoint.timestamp).toLocaleTimeString() : 'No Data'}
              </span>
              <span>Point: {currentIndex + 1} / {history.length}</span>
            </div>

            <input
              type="range"
              min="0"
              max={Math.max(0, history.length - 1)}
              value={currentIndex}
              onChange={(e) => {
                setCurrentIndex(Number(e.target.value));
                setIsLive(false);
                setIsPlaying(false);
              }}
              style={{ width: '100%', cursor: 'pointer', accentColor: vColor }}
              disabled={history.length === 0}
            />
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px', minWidth: '100px' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', color: isDark ? '#fff' : '#000', fontSize: '14px', fontWeight: '600' }}>
              <input
                type="checkbox"
                checked={isLive}
                onChange={(e) => {
                  setIsLive(e.target.checked);
                  if (e.target.checked) {
                    setIsPlaying(false);
                    setCurrentIndex(history.length - 1);
                    setAutoFollow(true); // Snap camera back on when Live is enabled
                  }
                }}
                style={{ width: '18px', height: '18px', accentColor: '#ff3b30' }}
              />
              <Activity size={16} color={isLive ? "#ff3b30" : (isDark ? '#888' : '#555')} />
              LIVE
            </label>
          </div>

        </div>
      </div>
    </div>
  );
}
